def count_scc(graph):
    n = len(graph)
    seen = [False] * n
    order = []
    def visit(g, u):
        seen[u] = True
        for v in range(n):
            if g[u][v] and not seen[v]:
                visit(g, v)
        order.append(u)
    for u in range(n):
        if not seen[u]:
            visit(graph, u)
    rev = [[graph[j][i] for j in range(n)] for i in range(n)]
    seen = [False] * n
    def mark(g, u):
        seen[u] = True
        for v in range(n):
            if g[u][v] and not seen[v]:
                mark(g, v)
    count = 0
    for u in reversed(order):
        if not seen[u]:
            mark(rev, u)
            count += 1
    return count

